import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"15、【謙】 艮下坤上","description":"橫渠易說 - 15、【謙】 艮下坤上","frontmatter":{"title":"15、【謙】 艮下坤上","description":"橫渠易說 - 15、【謙】 艮下坤上"},"headers":[],"relativePath":"classics/hengqu/017.md","filePath":"classics/hengqu/017.md"}'),l={name:"classics/hengqu/017.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_15、【謙】-艮下坤上" tabindex="-1">15、【謙】 艮下坤上 <a class="header-anchor" href="#_15、【謙】-艮下坤上" aria-label="Permalink to “15、【謙】 艮下坤上”">​</a></h1><h3 id="彖曰-謙亨-天道下濟而光明-地道卑而上行。天道虧盈而益謙-地道變盈而流謙-鬼神害盈而福謙-人道惡盈而好謙。謙尊而光-卑而不可踰-君子之終也。" tabindex="-1">彖曰：謙亨，天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可踰，君子之終也。 <a class="header-anchor" href="#彖曰-謙亨-天道下濟而光明-地道卑而上行。天道虧盈而益謙-地道變盈而流謙-鬼神害盈而福謙-人道惡盈而好謙。謙尊而光-卑而不可踰-君子之終也。" aria-label="Permalink to “彖曰：謙亨，天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可踰，君子之終也。”">​</a></h3><p>止於下，故光明。人樂尊之，故光而不揜；志下於人，故人不能加。天以廣大自然取貴，人自要尊大，須意、我、固、 必，欲順己尊己，又悅己之情，此所以取辱取怒也。“謙尊而光，卑而不可踰”，夫尊者謙則更光，卑者已謙，又如何踰之!此天德至虛者焉。以其能謙，故尊而益光，卑又無人可踰，蓋已謙矣，復如何踰越也!謙，天下之良德。</p><h3 id="象曰-地中有山-謙-君子以裒多益寡-稱物平施。" tabindex="-1">象曰：地中有山，謙，君子以裒多益寡，稱物平施。 <a class="header-anchor" href="#象曰-地中有山-謙-君子以裒多益寡-稱物平施。" aria-label="Permalink to “象曰：地中有山，謙，君子以裒多益寡，稱物平施。”">​</a></h3><p>隱高於卑，謙之象也。易大象皆是實事，卦爻小象則容有寓意而已。言“風自火出家人”，家人之道必自烹飪始；風，風也，教也，蓋言教家人之道必自此始也。又如言“木上有水井”，則明言井之實事也。又言“地中有山謙”，夫山者崇高之物，非謙而何!又如言“雲雷屯”，雲雷皆是氣之聚處，屯，聚也。多者寡者皆量宜下之。</p><h3 id="初六-謙謙君子-用涉大川-吉。-象曰-謙謙君子-卑以自牧也。" tabindex="-1">初六，謙謙君子，用涉大川，吉。 象曰：“謙謙君子”，卑以自牧也。 <a class="header-anchor" href="#初六-謙謙君子-用涉大川-吉。-象曰-謙謙君子-卑以自牧也。" aria-label="Permalink to “初六，謙謙君子，用涉大川，吉。 象曰：“謙謙君子”，卑以自牧也。”">​</a></h3><p>牧，逸也。</p><h3 id="六二-鳴謙-貞吉。-象曰-鳴謙貞吉-中心得也。" tabindex="-1">六二，鳴謙，貞吉。 象曰：“鳴謙貞吉”，中心得也。 <a class="header-anchor" href="#六二-鳴謙-貞吉。-象曰-鳴謙貞吉-中心得也。" aria-label="Permalink to “六二，鳴謙，貞吉。 象曰：“鳴謙貞吉”，中心得也。”">​</a></h3><p>體柔居正，故以謙獲譽，與上六之鳴異矣，故曰“貞吉”，［中心安之也］。</p><h3 id="九三-勞謙-君子有終-吉。-象曰-勞謙君子-萬民服也。" tabindex="-1">九三，勞謙，君子有終，吉。 象曰：“勞謙君子”，萬民服也。 <a class="header-anchor" href="#九三-勞謙-君子有終-吉。-象曰-勞謙君子-萬民服也。" aria-label="Permalink to “九三，勞謙，君子有終，吉。 象曰：“勞謙君子”，萬民服也。”">​</a></h3><p>(中心安之也。)有終則吉，人所難能。</p><h3 id="六四-無不利-撝謙。-象曰-無不利撝謙-不違則也。" tabindex="-1">六四，無不利，撝謙。 象曰：“無不利撝謙”，不違則也。 <a class="header-anchor" href="#六四-無不利-撝謙。-象曰-無不利撝謙-不違則也。" aria-label="Permalink to “六四，無不利，撝謙。 象曰：“無不利撝謙”，不違則也。”">​</a></h3><p>裒多益寡，無不盡道，舉措皆謙。</p><h3 id="六五-不富以其鄰-利用侵伐-無不利。-象曰-利用侵伐-徵不服也。" tabindex="-1">六五，不富以其鄰，利用侵伐，無不利。 象曰：“利用侵伐”，徵不服也。 <a class="header-anchor" href="#六五-不富以其鄰-利用侵伐-無不利。-象曰-利用侵伐-徵不服也。" aria-label="Permalink to “六五，不富以其鄰，利用侵伐，無不利。 象曰：“利用侵伐”，徵不服也。”">​</a></h3><h3 id="上六-鳴謙-利用行師-徵邑國。-象曰-鳴謙-志未得也-可用行師-徵邑國也。" tabindex="-1">上六，鳴謙，利用行師，徵邑國。 象曰：“鳴謙”，志未得也，可用行師，徵邑國也。 <a class="header-anchor" href="#上六-鳴謙-利用行師-徵邑國。-象曰-鳴謙-志未得也-可用行師-徵邑國也。" aria-label="Permalink to “上六，鳴謙，利用行師，徵邑國。 象曰：“鳴謙”，志未得也，可用行師，徵邑國也。”">​</a></h3><p>下應於三，其跡顯聞，故曰“鳴謙”；最上用謙，為眾所服，故“利用行師”。然聲鳴其謙，必志有求焉，非如六二之正也，三止於下，如邑國之未賓也。一雲：鳴謙則師有名。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
